/**
 * Task 26 — 3×3 sliding puzzle. Board = 9 cells, 0 = blank, solved = [1..8, 0].
 * Scrambles are generated by legal moves from the solved state → always solvable.
 * The server verifies a submission by replaying the move list.
 */
export const SIZE = 3;
export type Board = number[];
export const SOLVED: Board = [1, 2, 3, 4, 5, 6, 7, 8, 0];

/** Deterministic PRNG so every team gets the same scramble from the same seed. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function neighbors(index: number): number[] {
  const r = Math.floor(index / SIZE), c = index % SIZE;
  const out: number[] = [];
  if (r > 0) out.push(index - SIZE);
  if (r < SIZE - 1) out.push(index + SIZE);
  if (c > 0) out.push(index - 1);
  if (c < SIZE - 1) out.push(index + 1);
  return out;
}

export function isSolved(b: Board): boolean {
  return b.every((v, i) => v === SOLVED[i]);
}

/** Odd-width board: solvable ⇔ inversion count is even. */
export function isSolvable(b: Board): boolean {
  const tiles = b.filter((v) => v !== 0);
  let inv = 0;
  for (let i = 0; i < tiles.length; i++) for (let j = i + 1; j < tiles.length; j++) if (tiles[i] > tiles[j]) inv++;
  return inv % 2 === 0;
}

export function manhattan(b: Board): number {
  let d = 0;
  b.forEach((v, i) => {
    if (v === 0) return;
    const t = v - 1;
    d += Math.abs(Math.floor(i / SIZE) - Math.floor(t / SIZE)) + Math.abs((i % SIZE) - (t % SIZE));
  });
  return d;
}

/** Move the tile with the given number into the blank. Returns null if illegal. */
export function moveTile(b: Board, tile: number): Board | null {
  const ti = b.indexOf(tile), bi = b.indexOf(0);
  if (tile === 0 || ti < 0 || !neighbors(bi).includes(ti)) return null;
  const next = b.slice();
  next[bi] = tile;
  next[ti] = 0;
  return next;
}

export function scramble(seed: number, moves = 80, minManhattan = 14): Board {
  const rnd = mulberry32(seed);
  for (let attempt = 0; attempt < 50; attempt++) {
    let b = SOLVED.slice();
    let prevBlank = -1;
    for (let k = 0; k < moves; k++) {
      const bi = b.indexOf(0);
      const opts = neighbors(bi).filter((n) => n !== prevBlank); // no immediate undo
      const pick = opts[Math.floor(rnd() * opts.length)];
      b = moveTile(b, b[pick])!;
      prevBlank = bi;
    }
    if (!isSolved(b) && manhattan(b) >= minManhattan) return b;
  }
  throw new Error('could not reach scramble difficulty');
}

export interface PuzzleVerdict {
  valid: boolean;
  solved: boolean;
  moveCount: number;
  error?: string;
}

/** Replay tile moves from the start board; rejects any illegal move. */
export function verifyMoves(start: Board, tiles: number[]): PuzzleVerdict {
  let b = start.slice();
  for (let i = 0; i < tiles.length; i++) {
    const next = moveTile(b, tiles[i]);
    if (!next) return { valid: false, solved: false, moveCount: i, error: `illegal move #${i + 1}` };
    b = next;
  }
  return { valid: true, solved: isSolved(b), moveCount: tiles.length };
}
